#!/usr/bin/env bash
# PreToolUse hook (Read|Edit|Write|NotebookEdit): refuses a file generated by Burgr, and the
# edition of a framework file of the template set (reading it stays allowed).
# Generated = <GeneratedFilePrefix>*<GeneratedFileSuffix>.<ext>, framework =
# <GeneratedFilePrefix>*<FrameworkFileSuffix>.<ext>, read from every burgr.json of the
# repository (defaults "", ".g" and ".f"). Grep and Glob do not go through this hook: they stay allowed.
input=$(cat)
tool=$(printf '%s' "$input" | grep -oE '"tool_name" *: *"[^"]*"' | head -1 | sed -E 's/^"tool_name" *: *"//; s/"$//')
path=$(printf '%s' "$input" | grep -oE '"(file_path|notebook_path)" *: *"[^"]*"' | head -1 | sed -E 's/^"[a-z_]+" *: *"//; s/"$//')
[ -z "$path" ] && exit 0
path=${path//\\//}
name=${path##*/}
stem=${name%.*}
[ "$stem" = "$name" ] && exit 0

root=${CLAUDE_PROJECT_DIR:-.}
root=$(cygpath -u "$root" 2>/dev/null || printf '%s' "$root")
configs=$(find "$root" -maxdepth 4 \( -name node_modules -o -name .git -o -name bin -o -name obj -o -name .claude \) -prune -o -name burgr.json -print 2>/dev/null)
[ -z "$configs" ] && exit 0

setting() {
  if grep -qE "\"$2\"" "$1"; then
    grep -oE "\"$2\" *: *\"[^\"]*\"" "$1" | head -1 | sed -E 's/^"[A-Za-z]+" *: *"//; s/"$//'
  else
    printf '%s' "$3"
  fi
}

while IFS= read -r config; do
  prefix=$(setting "$config" GeneratedFilePrefix "")
  suffix=$(setting "$config" GeneratedFileSuffix ".g")
  framework=$(setting "$config" FrameworkFileSuffix ".f")
  case "$name" in "$prefix"*) ;; *) continue ;; esac
  if [ -n "$prefix$suffix" ]; then
    case "$stem" in *"$suffix")
      echo "Refused: $name is generated by Burgr (GeneratedFilePrefix='$prefix', GeneratedFileSuffix='$suffix' in ${config#"$root"/}). Do not read, edit or create it by hand, nor through a shell command. To find an extension point (partial, signature, type name), use Grep (output_mode content, -C). Behavior changes in the YAML model or in a hand-written extension point, then dotnet burgr. See AGENTS.md." >&2
      exit 2 ;;
    esac
  fi
  if [ "$tool" != "Read" ] && [ -n "$prefix$framework" ]; then
    case "$stem" in *"$framework")
      echo "Refused: $name is a framework file of the template set (FrameworkFileSuffix='$framework' in ${config#"$root"/}), rewritten at each generation. Read it to understand a behavior, but do not edit or create it by hand, nor through a shell command: adapt it through its extension points (partial, virtual, a replaced service registration). See AGENTS.md." >&2
      exit 2 ;;
    esac
  fi
done <<< "$configs"
exit 0
